# G3 - Additional bounded semantic READ_ONLY capabilities.
import re as _g3_re

_G3_JOB_ID = _g3_re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{2,120}$")
_G3_TERM = _g3_re.compile(r"^[A-Za-z0-9_.-]{2,64}$")
_G3_PATH = _g3_re.compile(r"^[A-Za-z0-9_./-]+$")
_G3_ROOTS = (
    "backend/modules/",
    "backend/tests/",
    "frontend/src/",
    "tools/mirror_sync/",
)
_G3_DENIED = {
    ".git", ".env", ".venv", "venv",
    "node_modules", "__pycache__", "dist", "build",
}
_G3_SENSITIVE = (
    "secret", "credential", "password", "token",
    "private_key", "api_key",
)

def _g3_context(request):
    context = str(request.get("bounded_context") or "").strip().upper()
    if not _g3_re.fullmatch(r"[A-Z0-9][A-Z0-9._-]{1,119}", context):
        raise SemanticCapabilityError("SEMANTIC_CONTEXT_INVALID")
    return context

def _g3_constraints(request, allowed):
    value = request.get("constraints")
    if not isinstance(value, Mapping):
        raise SemanticCapabilityError("SEMANTIC_CONSTRAINTS_INVALID")
    if set(value) - set(allowed):
        raise SemanticCapabilityError("SEMANTIC_CONSTRAINTS_UNSUPPORTED")
    return dict(value)

def _g3_scheduling(context):
    return {
        "project_id": "EDARSAHUB",
        "bounded_context": context,
        "priority_class": "NORMAL",
        "fairness_weight": 1,
        "max_parallelism": 1,
        "resource_claims": [],
        "conflict_domains": [context],
    }

def _g3_repository_builder(request):
    context = _g3_context(request)
    c = _g3_constraints(
        request, {"paths", "search_terms", "max_results"}
    )
    paths = c.get("paths")
    terms = c.get("search_terms")
    limit = c.get("max_results", 100)

    if not isinstance(paths, list) or not 1 <= len(paths) <= 20:
        raise SemanticCapabilityError("SEMANTIC_PATHS_INVALID")
    if not isinstance(terms, list) or not 1 <= len(terms) <= 20:
        raise SemanticCapabilityError("SEMANTIC_TERMS_INVALID")
    if type(limit) is not int or not 1 <= limit <= 100:
        raise SemanticCapabilityError("SEMANTIC_LIMIT_INVALID")

    for value in paths:
        if not isinstance(value, str) or not _G3_PATH.fullmatch(value):
            raise SemanticCapabilityError("SEMANTIC_PATH_INVALID")

        # Directory paths ending in / are valid.
        parts = value.rstrip("/").split("/")

        if (
            not value.startswith(_G3_ROOTS)
            or any(p in ("", ".", "..") for p in parts)
            or any(p in _G3_DENIED for p in parts)
            or any(
                marker in p.lower()
                for p in parts
                for marker in _G3_SENSITIVE
            )
        ):
            raise SemanticCapabilityError("SEMANTIC_PATH_FORBIDDEN")

    if any(
        not isinstance(t, str) or not _G3_TERM.fullmatch(t)
        for t in terms
    ):
        raise SemanticCapabilityError("SEMANTIC_TERMS_INVALID")

    return {
        "actions": [],
        "checks": [{
            "type": "repository_contract_audit",
            "request": {
                "paths": paths,
                "search_terms": terms,
                "max_results": limit,
            },
        }],
        "scheduling": _g3_scheduling(context),
    }

def _g3_result_builder(request):
    context = _g3_context(request)
    c = _g3_constraints(request, {"source_job_id"})
    job_id = c.get("source_job_id")

    if not isinstance(job_id, str) or not _G3_JOB_ID.fullmatch(job_id):
        raise SemanticCapabilityError("SEMANTIC_SOURCE_JOB_INVALID")

    return {
        "actions": [],
        "checks": [{
            "type": "worker_result_semantic_extract",
            "request": {
                "source_result": {
                    "branch": "worker/results",
                    "path": (
                        "worker_queue/results/"
                        + job_id + ".json"
                    ),
                },
            },
        }],
        "scheduling": _g3_scheduling(context),
    }

register_capability(
    SemanticCapability(
        code="REPOSITORY_CONTRACT_AUDIT_BOUNDED",
        modes=("READ_ONLY",),
        builder=_g3_repository_builder,
    )
)

register_capability(
    SemanticCapability(
        code="WORKER_RESULT_SEMANTIC_EXTRACT",
        modes=("READ_ONLY",),
        builder=_g3_result_builder,
    )
)

# G3 - Semantic capability tests.
import importlib.util as _g3_importlib
import sys as _g3_sys
import pytest as _g3_pytest

def _g3_module():
    source = (
        Path(__file__).resolve().parents[1]
        / "modules/worker_ingress/semantic_capabilities.py"
    )
    spec = _g3_importlib.spec_from_file_location(
        "_g3_semantic_capabilities", source
    )
    module = _g3_importlib.module_from_spec(spec)
    _g3_sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module

def _g3_build(code, constraints, context="WORKER_INGRESS"):
    module = _g3_module()
    return module.resolve_capability(code).builder({
        "bounded_context": context,
        "constraints": constraints,
    })

def test_g3_registration():
    module = _g3_module()
    names = module.registered_capabilities()
    assert "REPOSITORY_CONTRACT_AUDIT" in names
    assert "REPOSITORY_CONTRACT_AUDIT_BOUNDED" in names
    assert "WORKER_RESULT_SEMANTIC_EXTRACT" in names

def test_g3_rh_compatibility():
    result = _g3_build("REPOSITORY_CONTRACT_AUDIT", {}, "RH")
    assert result["actions"] == []
    assert result["checks"][0]["request"]["max_results"] == 200

def test_g3_repository_valid():
    result = _g3_build("REPOSITORY_CONTRACT_AUDIT_BOUNDED", {
        "paths": ["backend/modules/worker_ingress/"],
        "search_terms": ["semantic"],
        "max_results": 10,
    })
    assert result["actions"] == []
    assert result["checks"][0]["type"] == "repository_contract_audit"

@_g3_pytest.mark.parametrize("path", [
    "../secret",
    "/etc/passwd",
    ".git/config",
    "backend/modules/../../secret",
    "backend/modules/.env",
    "backend/modules/node_modules/file",
    "backend/modules/auth/passwords.py",
])
def test_g3_repository_rejects_paths(path):
    with _g3_pytest.raises(ValueError):
        _g3_build("REPOSITORY_CONTRACT_AUDIT_BOUNDED", {
            "paths": [path],
            "search_terms": ["semantic"],
        })

def test_g3_result_valid():
    result = _g3_build("WORKER_RESULT_SEMANTIC_EXTRACT", {
        "source_job_id": "BOS-GATE1-TEST",
    })
    assert result["actions"] == []
    assert result["checks"][0]["request"]["source_result"] == {
        "branch": "worker/results",
        "path": "worker_queue/results/BOS-GATE1-TEST.json",
    }

@_g3_pytest.mark.parametrize("job_id", [
    "../secret", "bad/name", "", "x",
])
def test_g3_result_rejects_job_id(job_id):
    with _g3_pytest.raises(ValueError):
        _g3_build("WORKER_RESULT_SEMANTIC_EXTRACT", {
            "source_job_id": job_id,
        })

def test_g3_result_rejects_arbitrary_refs():
    with _g3_pytest.raises(ValueError):
        _g3_build("WORKER_RESULT_SEMANTIC_EXTRACT", {
            "source_job_id": "BOS-GATE1-TEST",
            "branch": "other",
        })
